package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.nio.file.*;import org.json.*;
public class CacheIoTest {
 @Test public void cacheReadCompletesWhileNasWorkerIsBlocked()throws Exception{
  ExecutorService worker=Executors.newSingleThreadExecutor(),cacheIo=CacheIo.create();CountDownLatch workerEntered=new CountDownLatch(1),releaseWorker=new CountDownLatch(1),loaded=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();AtomicReference<String> title=new AtomicReference<>();AtomicBoolean daemon=new AtomicBoolean();AtomicInteger dispatched=new AtomicInteger();Path file=Files.createTempFile("synostream-cache-", ".json");
  try{Files.write(file,"[{\"title\":\"Cached fixture\"}]".getBytes(java.nio.charset.StandardCharsets.UTF_8));Future<?> busy=worker.submit(()->{workerEntered.countDown();try{releaseWorker.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(workerEntered.await(3,TimeUnit.SECONDS));Executor injected=read->{dispatched.incrementAndGet();cacheIo.execute(read);};CacheIo.load(injected,()->{try{daemon.set(Thread.currentThread().isDaemon());title.set(new JSONArray(new String(Files.readAllBytes(file),java.nio.charset.StandardCharsets.UTF_8)).getJSONObject(0).getString("title"));}catch(Throwable error){failure.set(error);}finally{loaded.countDown();}});assertTrue("Cache read must not wait for the NAS worker",loaded.await(3,TimeUnit.SECONDS));if(failure.get()!=null)throw new AssertionError(failure.get());assertEquals("Cached fixture",title.get());assertTrue(daemon.get());assertEquals(1,dispatched.get());assertFalse("NAS worker must still be blocked when the cache read finishes",busy.isDone());assertEquals(1,releaseWorker.getCount());}finally{releaseWorker.countDown();worker.shutdownNow();cacheIo.shutdownNow();assertTrue(cacheIo.awaitTermination(3,TimeUnit.SECONDS));Files.deleteIfExists(file);}
 }
 @Test public void cacheReadsAndSavesUseOneSerialDaemonThread()throws Exception{ExecutorService cacheIo=CacheIo.create();CountDownLatch readEntered=new CountDownLatch(1),releaseRead=new CountDownLatch(1);List<String> order=Collections.synchronizedList(new ArrayList<>());AtomicReference<Thread> reader=new AtomicReference<>();try{CacheIo.load(cacheIo,()->{reader.set(Thread.currentThread());readEntered.countDown();try{releaseRead.await();order.add("read");}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(readEntered.await(3,TimeUnit.SECONDS));Future<Thread> save=cacheIo.submit(()->{order.add("save");return Thread.currentThread();});assertFalse(save.isDone());releaseRead.countDown();Thread writer=save.get(3,TimeUnit.SECONDS);assertSame(reader.get(),writer);assertTrue(writer.isDaemon());assertEquals(List.of("read","save"),order);}finally{releaseRead.countDown();cacheIo.shutdownNow();assertTrue(cacheIo.awaitTermination(3,TimeUnit.SECONDS));}}
 @Test public void injectedExecutorOwnsReadScheduling(){List<Runnable> pending=new ArrayList<>();AtomicBoolean ran=new AtomicBoolean();CacheIo.load(pending::add,()->ran.set(true));assertFalse(ran.get());assertEquals(1,pending.size());pending.remove(0).run();assertTrue(ran.get());}
}
